// expect: exit 0
// keys: " "
// pixel: 40 40 1
// pixel: 215 95 1
// pixel: 39 40 0
// pixel: 128 96 0
// attr: 5 5 56
#pragma hires
int main(void)
{
    int i;
    cls();
    mode(1);
    for (i = 0; i < 56; i++) {
        ink(i % 7 + 1);
        draw(40, 40 + i, 215, 40 + i);
    }
    at(20, 10);
    print("PRESS A KEY");
    getkey();
    mode(0);
    return 0;
}
